1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: QuoteStep[];
20	};
21	
22	export type ScenarioResult = {
23	  results: unknown[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
38	
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const alikeItemGroups = (items: Item[]): Item[][] => [
43	  ...items
44	    .reduce(
45	      (groupsByType, item) =>
46	        groupsByType.set(item.type, [
47	          ...(groupsByType.get(item.type) ?? []),
48	          item,
49	        ]),
50	      new Map<string, Item[]>(),
51	    )
52	    .values(),
53	];
54	
55	const basePremiumOfGroup = (group: Item[]): number =>
56	  group.length === BLOCK_SIZE
57	    ? BLOCK_BASE_PREMIUM
58	    : group.reduce((total, item) => total + basePremiumOf(item), 0);
59	
60	const totalBasePremiumOf = (items: Item[]): number =>
61	  alikeItemGroups(items).reduce(
62	    (total, group) => total + basePremiumOfGroup(group),
63	    0,
64	  );
65	
66	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
67	
68	type Rule<Subject> = {
69	  appliesTo: (subject: Subject) => boolean;
70	  rate: number;
71	};
72	
73	const totalRateOf = <Subject,>(
74	  rules: Rule<Subject>[],
75	  subject: Subject,
76	): number =>
77	  rules.reduce(
78	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
79	    0,
80	  );
81	
82	const CURSE_SURCHARGE_RATE = 0.5;
83	const HIGH_ENCHANTMENT_THRESHOLD = 5;
84	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
85	
86	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
87	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
88	  {
89	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
90	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
91	  },
92	];
93	
94	const itemSurchargeOf = (item: Item): number =>
95	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
96	
97	const totalItemSurchargeOf = (items: Item[]): number =>
98	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
99	
100	const LOYALTY_YEARS_THRESHOLD = 2;
101	const LOYALTY_DISCOUNT_RATE = -0.2;
102	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
103	
104	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
105	
106	type PolicyContext = {
107	  customer: Customer;
108	  previousContracts: number;
109	};
110	
111	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
112	  {
113	    appliesTo: ({ customer }) =>
114	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
115	    rate: LOYALTY_DISCOUNT_RATE,
116	  },
117	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
118	  {
119	    appliesTo: ({ previousContracts }) => previousContracts > 0,
120	    rate: FOLLOW_UP_DISCOUNT_RATE,
121	  },
122	];
123	
124	const quotePremium = (items: Item[], policy: PolicyContext): number => {
125	  const basePremium = totalBasePremiumOf(items);
126	
127	  return roundedInMHPCOsFavour(
128	    basePremium +
129	      totalItemSurchargeOf(items) +
130	      basePremium * totalRateOf(POLICY_MODIFIER_RULES, policy) +
131	      PROCESSING_FEE,
132	  );
133	};
134	
135	export const runScenario = (scenario: Scenario): ScenarioResult => ({
136	  results: scenario.steps.map((step, previousContracts) => ({
137	    premium: quotePremium(step.items, {
138	      customer: scenario.customer,
139	      previousContracts,
140	    }),
141	  })),
142	});
